Cargo.toml.excerpt:
[workspace]
members = [
    "crates/*",
]
resolver = "2"

[workspace.package]
edition = "2021"
version = "1.61.0"
rust-version = "1.95.0"
authors = ["AAIF <ai-oss-tools@block.xyz>"]
license = "Apache-2.0"
repository = "https://github.com/aaif-goose/goose"
description = "An AI agent"

[workspace.lints.clippy]
uninlined_format_args = "allow"
string_slice = "warn"

[workspace.dependencies]
rmcp = { version = "3.9.0", default-features = false, features = ["schemars"] }
agent-client-protocol-schema = { version = "=1.9.1", default-features = false }
agent-client-protocol = { version = "2.2.0", default-features = false }
agent-client-protocol-http = { version = "2.2.0", default-features = false }
arboard = { version = "3", default-features = false }
